12	
13	option go_package = "gen/api/v1";
14	
15	service AttachmentService {
16	  // CreateAttachment creates a new attachment.
17	  rpc CreateAttachment(CreateAttachmentRequest) returns (Attachment) {
18	    option (google.api.http) = {
19	      post: "/api/v1/attachments"
20	      body: "attachment"
21	    };
22	    option (google.api.method_signature) = "attachment";
23	  }
24	  // ListAttachments lists all attachments.
25	  rpc ListAttachments(ListAttachmentsRequest) returns (ListAttachmentsResponse) {
26	    option (google.api.http) = {get: "/api/v1/attachments"};
27	  }
28	  // GetAttachment returns an attachment by name.
29	  rpc GetAttachment(GetAttachmentRequest) returns (Attachment) {
30	    option (google.api.http) = {get: "/api/v1/{name=attachments/*}"};
31	    option (google.api.method_signature) = "name";
32	  }
33	  // UpdateAttachment updates an attachment.
34	  rpc UpdateAttachment(UpdateAttachmentRequest) returns (Attachment) {
35	    option (google.api.http) = {
36	      patch: "/api/v1/{attachment.name=attachments/*}"
37	      body: "attachment"
38	    };
39	    option (google.api.method_signature) = "attachment,update_mask";
40	  }
41	  // DeleteAttachment deletes an attachment by name.
42	  rpc DeleteAttachment(DeleteAttachmentRequest) returns (google.protobuf.Empty) {
43	    option (google.api.http) = {delete: "/api/v1/{name=attachments/*}"};
44	    option (google.api.method_signature) = "name";
45	  }
46	  // BatchDeleteAttachments deletes multiple attachments in one request.
47	  rpc BatchDeleteAttachments(BatchDeleteAttachmentsRequest) returns (google.protobuf.Empty) {
48	    option (google.api.http) = {
49	      post: "/api/v1/attachments:batchDelete"
50	      body: "*"
51	    };
52	  }
53	}
54	
55	enum MotionMediaFamily {
56	  MOTION_MEDIA_FAMILY_UNSPECIFIED = 0;
57	  APPLE_LIVE_PHOTO = 1;
58	  ANDROID_MOTION_PHOTO = 2;
59	}
60	
61	enum MotionMediaRole {
62	  MOTION_MEDIA_ROLE_UNSPECIFIED = 0;
63	  STILL = 1;
64	  VIDEO = 2;
65	  CONTAINER = 3;
66	}
67	
68	message MotionMedia {
69	  MotionMediaFamily family = 1;
70	  MotionMediaRole role = 2;
71	  string group_id = 3;
72	  int64 presentation_timestamp_us = 4;
73	  bool has_embedded_video = 5;
74	}
75	
76	message Attachment {
77	  option (google.api.resource) = {
78	    type: "memos.api.v1/Attachment"
79	    pattern: "attachments/{attachment}"
80	    singular: "attachment"
81	    plural: "attachments"
82	  };
83	
84	  // The name of the attachment.
85	  // Format: attachments/{attachment}
86	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
87	
88	  // Output only. The creation timestamp.
89	  google.protobuf.Timestamp create_time = 2 [(google.api.field_behavior) = OUTPUT_ONLY];
90	
91	  // The filename of the attachment.
92	  string filename = 3 [(google.api.field_behavior) = REQUIRED];
